"""Identity experiment arm B: same scenes as idexp.py, generated by Qwen-Image-Edit-2511 from an identity
reference image (no LoRA; 2.1 LoRAs are not compatible with the Edit base). Config: config.local.yaml
(models_edit.*, character.reference_image, comfy_dir/url, times_csv). OUT_SUB env sets the output subfolder."""
import ast, json, os, sys, time, shutil, urllib.request, datetime
sys.path.insert(0, os.path.dirname(__file__)); import config
cfg=config.load(); ch=cfg["character"]; me=cfg.get("models_edit",{})
U=cfg["comfy_url"]; C=cfg["comfy_dir"]; CSV=cfg.get("times_csv"); OUT=os.environ.get("OUT_SUB","idexp/lora_plus_edit")
src=open(os.path.join(os.path.dirname(__file__),"idexp.py")).read(); tree=ast.parse(src)
G={n.targets[0].id:ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name) and n.targets[0].id in ("SCENES","REAL","SHOT","NEG")}
UNET=me.get("unet","qwen_image_edit_2511_int8_convrot.safetensors"); CLIP=me.get("clip","qwen_2.5_vl_7b_fp8_scaled.safetensors"); VAE=me.get("vae","qwen_image_vae.safetensors")
STEPS=int(me.get("steps",25)); CFG=float(me.get("cfg",4.0)); SHIFT=float(me.get("shift",3.1))
ref=os.path.basename(ch["reference_image"]); refname="idexp_ref_"+ref
shutil.copy(ch["reference_image"], os.path.join(C,"input",refname))
post=lambda p,d: json.load(urllib.request.urlopen(urllib.request.Request(U+p,data=json.dumps(d).encode(),headers={"Content-Type":"application/json"})))
res=[]
for n,(tag,scene) in enumerate(G["SCENES"]):
  seed=9001+n
  P=f"The same woman from image 1, with exactly the same face and identity, {scene}. {G['SHOT']}, {G['REAL']}"
  w={"1":{"class_type":"UNETLoader","inputs":{"unet_name":UNET,"weight_dtype":"default"}},
   "2":{"class_type":"CLIPLoader","inputs":{"clip_name":CLIP,"type":"qwen_image","device":"default"}},
   "3":{"class_type":"VAELoader","inputs":{"vae_name":VAE}},
   "4":{"class_type":"LoadImage","inputs":{"image":refname}},
   "5":{"class_type":"FluxKontextImageScale","inputs":{"image":["4",0]}},
   "6":{"class_type":"TextEncodeQwenImageEditPlus","inputs":{"clip":["2",0],"prompt":P,"vae":["3",0],"image1":["5",0]}},
   "13":{"class_type":"TextEncodeQwenImageEditPlus","inputs":{"clip":["2",0],"prompt":G["NEG"],"vae":["3",0],"image1":["5",0]}},
   "7":{"class_type":"ModelSamplingAuraFlow","inputs":{"model":["1",0],"shift":SHIFT}},
   "8":{"class_type":"EmptySD3LatentImage","inputs":{"width":1088,"height":1408,"batch_size":1}},
   "9":{"class_type":"KSampler","inputs":{"model":["7",0],"positive":["6",0],"negative":["13",0],"latent_image":["8",0],"seed":seed,"steps":STEPS,"cfg":CFG,"sampler_name":"euler","scheduler":"simple","denoise":1.0}},
   "10":{"class_type":"VAEDecode","inputs":{"samples":["9",0],"vae":["3",0]}},
   "11":{"class_type":"SaveImage","inputs":{"images":["10",0],"filename_prefix":f"{OUT}/{tag}_s{seed}"}}}
  t=time.time(); pid=post("/prompt",{"prompt":w})["prompt_id"]
  while True:
    time.sleep(0.5); h=json.load(urllib.request.urlopen(f"{U}/history/{pid}"))
    if pid in h: break
  dt=time.time()-t; st=h[pid]["status"].get("status_str")
  outs=[im["filename"] for o in h[pid]["outputs"].values() for im in o.get("images",[])]
  res.append(dict(tag=tag,seed=seed,status=st,sec=round(dt,1),file=outs[0] if outs else None)); print(res[-1],flush=True)
  if st!="success": print(json.dumps(h[pid]["status"])[-1500:],flush=True); break
  if CSV:
    with open(CSV,"a") as f: f.write(f"{datetime.datetime.now().astimezone().isoformat(timespec='seconds')},{UNET.rsplit('.',1)[0]}_nolora,edit_idexp_ref_cfg{CFG},1088x1408,{STEPS},{dt:.1f},{'first' if n==0 else 'warm'},{OUT}/{tag}_s{seed}\n")
os.makedirs(os.path.join(C,"output",OUT),exist_ok=True)
json.dump(res,open(os.path.join(C,"output",OUT,"results.json"),"w"),indent=1); print("DONE")
